allow:
Bash(powershell.exe -NoProfile -ExecutionPolicy Bypass -Command "
\\$proc = Start-Process -FilePath 'C:\\work\\mdview\\mdview.exe' -ArgumentList 'C:\\work\\mdview\\specs\\requirements.md' -PassThru
Start-Sleep -Milliseconds 3000
Add-Type @'
using System; using System.Runtime.InteropServices; using System.Collections.Generic; using System.Text;
public class WinAPI2 {
    public delegate bool EnumDelegate\(IntPtr hwnd, IntPtr lParam\);
    [DllImport\(\\"user32.dll\\"\)] public static extern bool EnumWindows\(EnumDelegate cb, IntPtr lp\);
    [DllImport\(\\"user32.dll\\"\)] public static extern int GetWindowText\(IntPtr hwnd, StringBuilder sb, int max\);
    [DllImport\(\\"user32.dll\\"\)] public static extern bool IsWindowVisible\(IntPtr hwnd\);
}
'@
\\$titles = @\(\)
[WinAPI2]::EnumWindows\({ param\(\\$h,\\$l\); if \([WinAPI2]::IsWindowVisible\(\\$h\)\) { \\$sb = New-Object System.Text.StringBuilder\(256\); [WinAPI2]::GetWindowText\(\\$h,\\$sb,256\); if \(\\$sb.Length -gt 0\) { \\$script:titles += \\$sb.ToString\(\) } }; return \\$true }, [IntPtr]::Zero\)
\\$titles | Where-Object { \\$_ -match 'mdview|requirements' }
\\$proc | Stop-Process -Force -ErrorAction SilentlyContinue
" 2>&1)
